use byond_dmb::{dmb::Dmb,bytecode};use std::{env,fs,path::PathBuf};fn main()->Result<(),Box<dyn std::error::Error>>{let a=env::args().collect::<Vec<_>>();let input=PathBuf::from(&a[1]);let output=PathBuf::from(&a[2]);let mut d=Dmb::from_bytes(&fs::read(&input)?)?;let target=d.procs.iter().position(|p|d.string(p.strings[0])==Some(b"/mob/verb/stop_pulling")).ok_or("verb")? as u32;for id in 0..d.procs.len(){if !matches!(d.string(d.procs[id].strings[0]),Some(b"/mob/living/proc/phase_in")|Some(b"/mob/living/proc/phase_out")){continue;}let mut words=d.proc_code_words(id).ok_or("code")?.to_vec();let decoded=bytecode::decode(&words).map_err(|e|format!("{e:?}"))?;let mut count=0;for ins in decoded{if [0x29,0x2a].contains(&ins.opcode){for at in ins.offset+1..ins.offset+ins.operands.len(){if words[at]==65503&&words[at+1]==target{words[at]=65504;count+=1;}}}}d.replace_proc_code(id,&bytecode::decode(&words).map_err(|e|format!("{e:?}"))?)?;println!("patched {id} {count} verb selectors");}d.validate_references()?;let bytes=d.to_bytes()?;Dmb::from_bytes(&bytes)?.validate_references()?;fs::create_dir_all(output.parent().ok_or("parent")?)?;fs::write(&output,bytes)?;fs::copy(input.with_extension("rsc"),output.with_extension("rsc"))?;Ok(())}
